from collections.abc import Iterable

from .money import MAX_AMOUNT_CENTS, amount_to_cents, cents_to_amount, format_amount


def make_invoice(amounts):
    if isinstance(amounts, (str, bytes)) or not isinstance(amounts, Iterable):
        raise ValueError("amounts must be a list of amounts")
    # Copy into a new list so the caller's input is never touched.
    items = list(amounts)
    total_cents = 0
    for item in items:
        total_cents += amount_to_cents(item)
    if total_cents > MAX_AMOUNT_CENTS:
        raise ValueError("invoice total must not exceed 1000000.00")
    return {"total": format_amount(cents_to_amount(total_cents)), "count": len(items)}
EOF
